<script setup>
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import {ElMessage} from 'element-plus'
import {createStudio,assetModel,categories,modelDB,dbCall} from './studio'
const emit=defineEmits(['close'])
const host=ref(),fileInput=ref(),category=ref('stacker'),filter=ref('all'),units=ref('auto'),busy=ref(false),selection=ref(null),placements=ref([]),mode=ref('translate'),snap=ref(true),ready=ref(false)
const assets=ref(categories.slice(0,4).map(([id,label])=>({id:'builtin-'+id,name:label+' · 示意模型',category:id,builtin:true,units:'m'})))
const filtered=computed(()=>assets.value.filter(a=>filter.value==='all'||a.category===filter.value))
let studio,db,restoring=true,alive=true
const label=id=>categories.find(c=>c[0]===id)?.[1]||'其他设备'
function saveLayout(list){placements.value=list;if(!restoring)try{localStorage.setItem('warehouse-studio-layout-v1',JSON.stringify(list))}catch{ElMessage.warning('布局本地保存失败，请导出布局备份')}}
async function place(asset,drop){try{const result=await studio.add(asset,{},drop);if(result)studio.focus(result.id)}catch(e){ElMessage.error('模型加载失败：'+e.message)}}
function drag(asset,event){event.dataTransfer.setData('application/warehouse-asset',asset.id);event.dataTransfer.effectAllowed='copy'}
function drop(event){const asset=assets.value.find(a=>a.id===event.dataTransfer.getData('application/warehouse-asset'));if(asset)place(asset,{x:event.clientX,y:event.clientY})}
async function importModel(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(!['glb','gltf','stl','obj'].includes(ext)){ElMessage.warning('SolidWorks 原生 SLDPRT / SLDASM / STEP 请先转换为 GLB、STL 或 OBJ');return}if(file.size>30*1024*1024){ElMessage.warning('单模型限制 30 MB，请先简化网格');return}busy.value=true
 try{const buffer=await file.arrayBuffer();if(ext==='gltf'){const data=JSON.parse(new TextDecoder().decode(buffer));if([...(data.buffers||[]),...(data.images||[])].some(x=>x.uri&&!x.uri.startsWith('data:')))throw Error('请打包为 GLB，或使用内嵌资源的 glTF；不支持外部纹理/二进制文件')}
 const asset={id:crypto.randomUUID(),name:file.name,category:category.value,units:units.value==='auto'?(ext==='glb'||ext==='gltf'?'m':'mm'):units.value,ext,buffer};const preview=await assetModel(asset);preview.traverse(o=>{o.geometry?.dispose();const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>{if(m){Object.values(m).filter(v=>v?.isTexture).forEach(t=>t.dispose());m.dispose()}})});if(!alive)return
 if(db)await dbCall(db,'put',asset);assets.value.push(asset);filter.value=asset.category;ElMessage.success(db?'模型已按设备分类保存，拖入画布即可布置':'模型已加载到本次会话，本地存储不可用')
 }catch(e){ElMessage.error('导入失败：'+e.message)}finally{busy.value=false}}
function edit(kind,index,value){if(!selection.value)return;const data=[...selection.value[kind]];data[index]=Number(value)|| (kind==='scale'?1:0);if(kind==='scale')data[index]=Math.max(.01,data[index]);studio.update(selection.value.id,{[kind]:data})}
function exportLayout(){const data={version:1,units:'m',assets:assets.value.map(({buffer,...meta})=>meta),placements:studio.list(),note:'布局 JSON 不包含导入模型二进制文件，请另行保留源模型。模型本地保存在当前浏览器。'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='warehouse-layout.json';a.click();URL.revokeObjectURL(url)}
onMounted(async()=>{try{studio=createStudio(host.value,v=>selection.value=v,saveLayout);try{db=await modelDB();const loaded=await dbCall(db,'getAll');if(!alive){db.close();return}assets.value.push(...loaded)}catch{ElMessage.warning('当前浏览器不能保存模型，导入模型仅在本次会话可用')}
 let saved=[];try{saved=JSON.parse(localStorage.getItem('warehouse-studio-layout-v1')||'[]')}catch{}let missing=0
 for(const p of Array.isArray(saved)?saved:[]){if(!alive)return;const a=assets.value.find(a=>a.id===p.assetId);if(a&&Array.isArray(p.position)&&p.position.length===3){try{await studio.add(a,p)}catch{missing++}}else missing++}
 if(missing)ElMessage.warning(missing+' 个模型未能恢复，请重新导入源模型');restoring=false;ready.value=true;placements.value=studio.list()
 }catch(e){ElMessage.error('编辑器启动失败：'+e.message)}})
onBeforeUnmount(()=>{alive=false;studio?.dispose();db?.close()})
</script>
<template>
 <div class="model-studio" role="dialog" aria-label="设备模型编辑器">
  <header class="studio-header"><div><span class="eyebrow">WAREHOUSE MODEL STUDIO</span><h2>设备模型库与场景布置</h2></div><div><el-button :disabled="!ready" @click="exportLayout">导出布局</el-button><el-button type="primary" @click="emit('close')">返回看板</el-button></div></header>
  <div class="studio-body"><aside class="studio-library"><h3>设备资产库 <span>{{assets.length}}</span></h3><p>按设备分类管理，将模型拖入画布；触屏可点击「放置」。</p><el-select v-model="filter" aria-label="筛选设备分类"><el-option label="全部设备" value="all"/><el-option v-for="[id,name] in categories" :key="id" :label="name" :value="id"/></el-select><div class="asset-list"><article v-for="a in filtered" :key="a.id" class="asset-card" draggable="true" @dragstart="drag(a,$event)"><div class="asset-symbol">{{a.category==='stacker'?'Ⅱ':a.category==='rack'?'▦':a.category==='conveyor'?'≋':'▤'}}</div><div><b>{{a.name}}</b><small>{{label(a.category)}} · {{a.builtin?'内置':a.ext.toUpperCase()}} · {{a.units}}</small></div><el-button size="small" :disabled="!ready" @click="place(a)">放置</el-button></article></div><section class="studio-import"><h3>导入设备模型</h3><label>设备分类</label><el-select v-model="category" aria-label="导入设备分类"><el-option v-for="[id,name] in categories" :key="id" :label="name" :value="id"/></el-select><label>模型单位</label><el-select v-model="units" aria-label="模型单位"><el-option label="自动：GLB / glTF 米，STL / OBJ 毫米" value="auto"/><el-option label="毫米 mm" value="mm"/><el-option label="米 m" value="m"/></el-select><input ref="fileInput" type="file" accept=".glb,.gltf,.stl,.obj,.sldprt,.sldasm,.step,.stp" hidden @change="importModel"><el-button type="primary" :loading="busy" :disabled="!ready" @click="fileInput.click()">选择模型文件</el-button><p>SolidWorks：另存为 STL（网格），或将装配体转换为 GLB。GLB 保留材质与层级；STL 仅保留几何。OBJ 不加载外部 MTL。原生 CAD 文件需先转换，单文件 ≤30 MB。</p></section></aside>
  <section class="studio-workspace"><nav><el-radio-group v-model="mode" @change="v=>studio?.mode(v)" size="small"><el-radio-button value="translate">移动</el-radio-button><el-radio-button value="rotate">旋转</el-radio-button><el-radio-button value="scale">缩放</el-radio-button></el-radio-group><el-switch v-model="snap" active-text="0.5 m 网格吸附" @change="v=>studio?.snap(v)"/><span>{{placements.length}} 台设备</span></nav><div ref="host" class="studio-canvas" @dragover.prevent @drop.prevent="drop"></div><div class="studio-hint">拖拽设备到网格 · 点击模型选择 · 拖动坐标轴编辑 · 空白处拖动旋转视角 · 滚轮缩放</div></section>
  <aside class="studio-properties"><h3>场景设备</h3><el-empty v-if="!placements.length" description="从左侧放置第一台设备" :image-size="60"/><button v-for="p in placements" :key="p.id" class="placed-item" :class="{active:selection?.id===p.id}" @click="studio.select(p.id)">{{p.name}}<small>{{label(assets.find(a=>a.id===p.assetId)?.category)}}</small></button><section v-if="selection" class="property-editor"><h3>变换属性</h3><div v-for="[key,name] in [['position','位置 / m'],['rotation','旋转 / rad'],['scale','缩放倍率']]" :key="key"><label>{{name}}</label><div v-for="(axis,i) in ['X','Y','Z']" :key="axis" class="axis-editor"><span>{{axis}}</span><el-input-number :model-value="selection[key][i]" :min="key==='scale'?.01:undefined" :step="key==='rotation'?.1:.5" :precision="2" @change="v=>edit(key,i,v)"/></div></div><el-button @click="studio.focus(selection.id)">聚焦模型</el-button><el-button type="danger" @click="studio.remove(selection.id)">删除实例</el-button></section><p class="studio-note">模型和布局保存在当前浏览器。布置的导入模型为静态展示，不自动绑定仿真或真实设备报警。</p></aside></div>
 </div>
</template>
<style>
.model-studio{position:fixed;inset:0;z-index:100;background:#07121f;color:#d6e8f4;display:grid;grid-template-rows:86px minmax(0,1fr);padding:0 18px 18px}.studio-header{border-bottom:1px solid #254353;min-height:0}.studio-header h2{font-size:21px;margin:7px 0}.studio-body{display:grid;grid-template-columns:280px minmax(0,1fr) 250px;gap:14px;padding-top:14px;min-height:0}.studio-library,.studio-properties{overflow:auto;padding:16px;background:#102131;border:1px solid #254353;border-radius:8px;display:block}.model-studio h3{font-size:14px;margin:0 0 14px;display:flex;justify-content:space-between}.model-studio p,.studio-note{font-size:11px;color:#91adbf;line-height:1.8}.model-studio .el-select{width:100%;margin-bottom:10px}.asset-card{display:flex;align-items:center;gap:8px;padding:12px 8px;border:1px solid #315267;border-radius:6px;background:#142c3d;margin:9px 0;cursor:grab}.asset-card b{display:block;font-size:12px;word-break:break-all}.asset-card small{display:block;font-size:10px;color:#90aebb;margin-top:6px}.asset-card>div:nth-child(2){flex:1;min-width:0}.asset-symbol{font-size:24px;color:#4bddc9}.studio-import{margin-top:24px;border-top:1px solid #315267;padding-top:18px}.studio-import label,.property-editor label{display:block;font-size:12px;color:#9bb8ca;margin:10px 0}.studio-workspace{display:grid;grid-template-rows:auto minmax(0,1fr) auto;border:1px solid #315267;border-radius:8px;overflow:hidden;min-width:0}.studio-workspace nav{display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:12px;background:#102131}.studio-workspace nav>span{margin-left:auto;font-size:12px;color:#82b9be}.studio-canvas{min-height:0;position:relative}.studio-canvas canvas{display:block;touch-action:none}.studio-hint{font-size:10px;color:#8aabbf;background:#102131;padding:12px}.placed-item{display:block;width:100%;text-align:left;padding:10px;margin:7px 0;border:1px solid #2c4b5e;background:#102b3a;color:#cce8ef;border-radius:5px;cursor:pointer;word-break:break-all}.placed-item.active{border-color:#35cfbe}.placed-item small{display:block;color:#83a8b6;margin-top:5px}.property-editor{margin-top:24px}.axis-editor{display:flex;align-items:center;gap:8px;margin:6px 0;font-size:12px}.axis-editor .el-input-number{width:160px}.property-editor>.el-button{margin:12px 5px 0 0}.studio-note{margin-top:20px}@media(max-width:1100px){.studio-body{grid-template-columns:220px minmax(0,1fr)}.studio-properties{grid-column:1/-1;max-height:230px}.model-studio{overflow:auto;grid-template-rows:auto auto}.studio-body{grid-template-rows:600px auto}.studio-header{min-height:85px;flex-wrap:wrap;padding:10px 0}}@media(max-width:650px){.model-studio{padding:0 10px 10px}.studio-header h2{font-size:17px}.studio-body{display:flex;flex-direction:column}.studio-workspace{order:-1;height:520px;flex-shrink:0}.studio-library{max-height:620px}.studio-properties{max-height:none}.studio-header .el-button{padding:8px}.studio-hint{line-height:1.7}.studio-workspace nav{gap:8px}}
</style>
